 private void language(boolean source){PopupMenu menu=new PopupMenu(this,source?fromBadge:toBadge);String[] codes={"uz-Latn","en","ru","uz-Cyrl"},labels={"O‘zbek","English","Русский","Ўзбек"};for(int i=0;i<codes.length;i++)menu.getMenu().add(0,i,i,labels[i]);menu.setOnMenuItemClickListener(item->{String from=source?codes[item.getItemId()]:preferences.source(),to=source?preferences.target():codes[item.getItemId()];if(!TextTools.supported(from,to)){if(source)to=from.equals("uz-Latn")?"en":"uz-Latn";else from=to.equals("uz-Latn")?"en":"uz-Latn";}preferences.languages(from,to);refreshLanguages();schedule();return true;});menu.show();}
 private void schedule(){generation++;if(pending!=null)handler.removeCallbacks(pending);if(cancel!=null)cancel.cancel();if(work!=null)work.cancel(true);result=null;if(output==null)return;output.setText("");String text=input.getText().toString();if(text.trim().isEmpty()){notice.setText("Results appear after a pause.");return;}notice.setText("Working…");long id=generation;pending=()->run(text,id);handler.postDelayed(pending,650);}
 private void run(String text,long id){TextTools.Tool selected=tool;String source=preferences.source(),target=preferences.target();WritingServices.Options options=preferences.options();WritingServices.Cancel token=new WritingServices.Cancel();cancel=token;int start=input.getSelectionStart(),end=input.getSelectionEnd();work=executor.submit(()->{try{Engine.Result response=engine.process(selected,text,start,end,source,target,options,token);token.check();handler.post(()->{if(id==generation){result=response;output.setText(Ui.rendered(text,response));notice.setText(response.summary);}});}catch(CancellationException ignored){}catch(Exception error){handler.post(()->{if(id==generation){output.setText("");notice.setText(error instanceof IllegalArgumentException?error.getMessage():"The service is unavailable. Check your connection and try again.");}});}});}
 private boolean accessibilityEnabled(){String enabled=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);ComponentName ours=new ComponentName(this,SuggestionService.class);if(enabled!=null)for(String value:enabled.split(":"))if(ours.equals(ComponentName.unflattenFromString(value)))return true;return false;}
 private void updateStatus(){boolean access=accessibilityEnabled();status.setText(access?(preferences.enabled()?(SuggestionService.connected!=null?"Ready to write · popup suggestions enabled":"Accessibility enabled · connecting…"):"Suggestions paused"):(preferences.enabled()?"Enable Accessibility to show cross-app suggestions":"Popup suggestions need Accessibility"));toggle.setText(preferences.enabled()?"Pause suggestions":"Enable suggestions");toggle.setBackground(Ui.rounded(preferences.enabled()?Ui.CYAN:Ui.GREEN,20,this));}
 private void toggle(){if(!preferences.consent()){disclosure(()->{preferences.enabled(true);updateStatus();openPermissions();});return;}preferences.enabled(!preferences.enabled());updateStatus();if(preferences.enabled()&&!accessibilityEnabled())openPermissions();}
 private void permissions(){if(!preferences.consent())disclosure(this::openPermissions);else openPermissions();}
 private void disclosure(Runnable approved){new AlertDialog.Builder(this).setTitle("Show suggestions in other apps").setMessage("Sayqalchi uses Accessibility to read the focused editable field and display a popup while you type. It changes text only when you tap Use. Password fields and protected apps are skipped.\n\nFormat stays on your phone. Only your chosen default service runs automatically. Translate sends the draft to your selected provider; Izohchi sends a word or phrase to Izoh.uz. No typing history is saved.\n\nYou can pause in the app or Quick Settings. You must enable Sayqalchi yourself in Android Accessibility settings.").setNegativeButton("Not now",null).setPositiveButton("Continue",(dialog,which)->{preferences.values.edit().putBoolean("disclosureAccepted",true).apply();approved.run();}).show();}
 private void openPermissions(){startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}
 @Override protected void onResume(){super.onResume();if(preferences!=null)updateStatus();}
